window.kbPageData["views/entry/k-fc10ef44d2f50821"] = {"key":"entry/k-fc10ef44d2f50821","state":{"route":"entry/k-fc10ef44d2f50821"},"node":{"id":"k-fc10ef44d2f50821","mode":"k","title":"构建就业友好型发展方式","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["employment"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["就业、社保与公共服务"],"资料类别":["非时政"]},"directorySummary":"3.构建就业友好型发展方式\n党的二十届四中全会通过的《中共中央关于制定国民经济和社会发展第十五个五年规划\n的建议》对促进高质量充分就业作出重要部署，并提出“构建就业友好型发展方式”。习近\n平总书记深刻指出，“就业是最基本的民生，事关人民群众切身利益，事关经济社会健康发\n展，事关国家长治久安”，深刻揭…","sources":[{"id":"6e6c48f4e0e6ff3b","label":"构建就业友好型发展方式","topic":"就业、社保与公共服务","category":"非时政","text":"3.构建就业友好型发展方式\n党的二十届四中全会通过的《中共中央关于制定国民经济和社会发展第十五个五年规划\n的建议》对促进高质量充分就业作出重要部署，并提出“构建就业友好型发展方式”。习近\n平总书记深刻指出，“就业是最基本的民生，事关人民群众切身利益，事关经济社会健康发\n展，事关国家长治久安”，深刻揭示了就业与发展的辩证统一关系，为新时代就业工作提供\n了根本遵循。\n所谓就业友好型发展方式，就是将就业优先理念贯穿于经济社会发展全过程各领域，实\n现经济增长与就业扩容良性互动、结构优化与就业提质相互促进、创新驱动与就业赋能有机\n统一，让发展成果更多更公平惠及全体劳动者，为中国式现代化筑牢民生根基。\n——《人民网》","source":{"doc":"6cbfb01fe723bba64b75","first":40,"last":40,"page":40,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-fc10ef44d2f50821":[]}};
